            */
            bool? IEEE_754_TOTAL_ORDER; // 2:
            /**
            Thrift type Int96TimestampOrder is an empty struct: carried as a bool presence flag.
            */
            bool? INT96_TIMESTAMP_ORDER; // 3:
        }

