            In files encrypted with AAD prefix without storing it,
            readers must supply the prefix *
            */
            bool? supply_aad_prefix; // 3:
        }

        /**
        Thrift union: exactly one of the fields is set.
        */
        public class EncryptionAlgorithm {
            AesGcmV1 AES_GCM_V1; // 1:
            AesGcmCtrV1 AES_GCM_CTR_V1; // 2:
        }

        /**
        Description for file metadata
        */
        public class FileMetaData {
            /**
            Version of this file
            As of December 2025, there is no agreed upon consensus of what constitutes
            version 2 of the file. For maximum compatibility with readers, writers should
            always populate "1" for version. For maximum compatibility with writers,
            readers should accept "1" and "2" interchangeably.  All other versions are
            reserved for potential future use-cases.
            */
            [X] int version; // 1:
            /**
            Parquet schema for this file.  This schema contains metadata for all the columns.
            The schema is represented as a tree with a single root.  The nodes of the tree
            are flattened to a list by doing a depth-first traversal.
            The column metadata contains the path in the schema for that column which can be
            used to map columns to nodes in the schema.
            The first element is the root *
            */
            SchemaElement[,,] schema; // 2:
            /**
            Number of rows in this file *
            */
            [X] long num_rows; // 3:
            /**
            Row groups in this file *
            */
            RowGroup[,,] row_groups; // 4:
            /**
            Optional key/value metadata *
            */
            KeyValue[,,] key_value_metadata; // 5:
            /**
            String for application that wrote this file.  This should be in the format
            &lt;Application&gt; version &lt;App Version&gt; (build &lt;App Build Hash&gt;).
            e.g. impala version 1.0 (build 6cf94d29b2b7115df4de2c06e2ab4326d721eb55)
            */
            string created_by; // 6:
            /**
            Sort order used for the min_value and max_value fields in the Statistics
            objects and the min_values and max_values fields in the ColumnIndex
            objects of each column in this file. Sort orders are listed in the order
            matching the columns in the schema. The indexes are not necessarily the same
            though, because only leaf nodes of the schema are represented in the list
            of sort orders.
            Without column_orders, the meaning of the min_value and max_value fields
            in the Statistics object and the ColumnIndex object is undefined. To ensure
            well-defined behaviour, if these fields are written to a Parquet file,
            column_orders must be written as well.
            The obsolete min and max fields in the Statistics object are always sorted
            by signed comparison regardless of column_orders.
            */
            ColumnOrder[,,] column_orders; // 7:
            /**
            Encryption algorithm. This field is set only in encrypted files
            with plaintext footer. Files with encrypted footer store algorithm id
            in FileCryptoMetaData structure.
            */
            EncryptionAlgorithm encryption_algorithm; // 8:
            /**
            Retrieval metadata of key used for signing the footer.
            Used only in encrypted files with plaintext footer.
            */
            Binary[,,] footer_signing_key_metadata; // 9:
        }

        /**
        Crypto metadata for files with encrypted footer *
        */
        public class FileCryptoMetaData {
            /**
            Encryption algorithm. This field is only used for files
            with encrypted footer. Files with plaintext footer store algorithm id
            inside footer (FileMetaData structure).
            */
            EncryptionAlgorithm encryption_algorithm; // 1:
            /**
            Retrieval metadata of key used for encryption of footer,
            and (possibly) columns *
            */
            Binary[,,] key_metadata; // 2:
        }

        // ═════════════════════════ topology ═════════════════════════

        // Calls the services (Left side).
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Client : Host { }

        // Implements the services (Right side).
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Server : Host { }

        // No services in the source: every pack may be sent by either side.
        interface ClientServer : Connects<Client, Server> {
            // Every pack of the project, in both directions; the FSM never transitions.
            // SkipName keeps the metadata attribute classes declared in this interface out of the pack set.
            [_____lr_____<@parquet>(SkipName: @"Attribute$")]
            struct Start { }
        }

        // ═════════════════════════ Thrift metadata attribute ═════════════════════════

        // Not read by AdHoc; kept so a Thrift annotation survives the conversion.

        /** Thrift annotation `(key = "value")` on the field or its type. */
        [AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
        public class AnnotationAttribute : Attribute { public AnnotationAttribute(string key, string value) { } }
    }
}
